let services=[['Medžių genėjimas','Iki 30 cm','vnt.',25,'Paslauga'],['Medžių genėjimas','31–80 cm','vnt.',55,'Paslauga'],['Medžio pjovimas iš autobokštelio','Iki 30 cm','vnt.',60,'Paslauga'],['Medžio pjovimas iš autobokštelio','31–80 cm','vnt.',110,'Paslauga'],['Vejos pjovimas','Prižiūrima veja','a',4,'Paslauga'],['Aukštos žolės pjovimas','Apleista teritorija','a',8,'Paslauga'],['Traktoriaus nuoma','Su vairuotoju','val.',38,'Technika'],['Lapų siurblys','Įrenginio naudojimas','val.',15,'Technika'],['Šlavimo įrenginys','Įrenginio naudojimas','val.',18,'Technika'],['Darbuotojo darbas','Teritorijos tvarkymas','val.',14,'Darbas'],['Sunkvežimio nuoma','Darbo laikas','val.',42,'Technika'],['Sunkvežimio rida','Nuvažiuotas atstumas','km',1.3,'Technika'],['Greideriavimas','Kelių priežiūra','km',95,'Paslauga'],['Sniego valymas','Mechanizuotai','km',32,'Paslauga'],['Smėlio ir druskos mišinys','Panaudota medžiaga','t',75,'Medžiaga'],['Patalpų iškraustymas','Darbuotojo darbas','val.',16,'Darbas'],['Šakų išvežimas','Surinkimas ir išvežimas','m³',18,'Paslauga'],['Smulkūs remonto darbai','Darbuotojo darbas','val.',20,'Darbas']].map((r,i)=>({id:'S'+(i+1),name:r[0],variant:r[1],unit:r[2],rate:r[3],type:r[4]}));
let names=['Mechanizuotas lapų surinkimas','Parkų ir želdinių priežiūra','Žiemos tarnybos darbai','Greideriavimo darbai','Socialinio būsto iškraustymas','Medžių genėjimas prie mokyklos','Privataus sklypo medžių pjovimas','Lauko suoliukų remontas','Teritorijos tvarkymas po renginio','Skubus šakų išvežimas'];
let orders=names.map((title,i)=>({id:'U'+(i+1),number:'UZ-2026-'+String(201+i),title,contractId:['C2','C1','C4','C3','C5','C1','C6','C5','C2','C1'][i],eldership:elderships[i%6],divisionId:['D2','D1','D3','D3','D4','D1','D1','D4','D2','D1'][i],owner:['P2','P1','P3','P3','P4','P1','P1','P4','P2','P1'][i],client:i===6?'Jonas Pavyzdys':'',contact:i===6?'+370 600 12345':'',location:['Parko g. 12','Miesto parkas','Šiaurinis maršrutas','Ąžuolų kelias','Centro g. 8','Mokyklos g. 4','Sodų g. 17','Parko alėja','Renginių aikštė','Miško g. 6'][i],mode:i<4?'Mėnesinis':'Vienkartinis',status:['Vykdomas','Vykdomas','Naujas','Suplanuotas','Atliktas','Atliktas','Naujas','Atliktas','Vykdomas','Atliktas'][i],due:i<4?'':offset(i===8?-1:i%5),created:offset(-8+i%4),description:i===0?'Faktiniai darbai papildomi kasdien: traktorius, lapų siurblys, šlavimo įrenginys ir darbuotojai. Galutinė apimtis paaiškės mėnesio pabaigoje.':i===6?'Prieš pradedant darbus suderinti apimtį vietoje ir gauti kliento parašą užsakymo blanke.':'Registruoti atliktus darbus ir jų faktinius kiekius.',comments:[],events:[{text:'Užsakymas užregistruotas',at:stamp()}]}));
let entries=[];let add=(o,s,q,ago,note='',people=[])=>{let order=orders[o-1],srv=services[s-1];entries.push({id:'W'+(entries.length+1),date:offset(-ago),contractId:order.contractId,orderId:order.id,eldership:order.eldership,divisionId:order.divisionId,location:order.location,serviceId:srv.id,quantity:q,rate:srv.rate,employees:people.length?people:[order.owner],resource:srv.type==='Technika'?srv.name:'',note,actId:''})};
